// Minimal stand-in for express-rate-limit, mirroring the express, aws-sdk and
// stripe stubs already tracked under backend/node_modules so that `npm test`
// runs without a full install. Counts nothing; real limiting comes from the
// published package once dependencies are installed.
function rateLimit() {
  return function rateLimitMiddleware(_req, _res, next) {
    if (typeof next === 'function') next();
  };
}

module.exports = rateLimit;
module.exports.default = rateLimit;
module.exports.rateLimit = rateLimit;
